import{_ as i,c as l,a,aS as e}from"./chunks/framework.BB9D2qGO.js";const b=JSON.parse('{"title":"国产好看的电影","description":"","frontmatter":{},"headers":[],"relativePath":"note/movie/国产movie.md","filePath":"note/movie/国产movie.md","lastUpdated":1753880156000}'),t={name:"note/movie/国产movie.md"},p=e('<h1 id="国产好看的电影" tabindex="-1">国产好看的电影 <a class="header-anchor" href="#国产好看的电影" aria-label="Permalink to &quot;国产好看的电影&quot;">​</a></h1><p>都是博主看过的电影，有很老的，也有新出的，里面不乏有些小众但是非常好看偏门的好作品，分享给大家。</p><h2 id="年会不能停" tabindex="-1">年会不能停 <a class="header-anchor" href="#年会不能停" aria-label="Permalink to &quot;年会不能停&quot;">​</a></h2><ul><li>2023-12-29中国大陆117分钟</li><li>类型：搞笑剧情</li><li>导演：董润年</li><li>主演：董成鹏白客庄达菲王迅孙艺洲</li><li>百科：在一个配件厂兢兢业业许多年的钳工胡建林(大鹏 饰),偶然接到一纸调令,命他马上到集团总公司赴任。淳朴老实的建林还...</li></ul><p>2023年看过最好的电影</p><p><img src="https://p4.itc.cn/q_70/images03/20231229/36f68991f9d1464cb31bde07d0837b4e.png" alt=""></p><h2 id="胜券在握" tabindex="-1">胜券在握 <a class="header-anchor" href="#胜券在握" aria-label="Permalink to &quot;胜券在握&quot;">​</a></h2><ul><li>2024-11-15 中国大陆 135分钟</li><li>类型：剧情</li><li>导演：刘循子墨</li><li>主演：邓超 邓家佳 郑云龙 喻恩泰 张本煜</li><li>百科：在科技公司工作的11号员工白胜(邓超 饰)被郝大哥(杨皓宇 饰)催债,又惨遭公司裁员,为了赢回属于自己的800万...</li></ul><p>2024年看过最好的电影</p><p><img src="https://q5.itc.cn/images01/20241119/c1167426b4924c1db839b835cebb8a80.jpeg" alt=""></p><h2 id="地久天长" tabindex="-1">地久天长 <a class="header-anchor" href="#地久天长" aria-label="Permalink to &quot;地久天长&quot;">​</a></h2><ul><li>2019年3月22日 中国大陆 175分钟</li><li>类型：剧情、家庭</li><li>导演：王小帅</li><li>主演：王景春 咏梅 齐溪 王源</li><li>百科：影片讲述两个原本亲密无间的家庭因为一场突如其来的意外导致关系疏远，两家人的命运也因此发生了巨大的改变。两家人在时代的洪流中经历着各自的痛苦与挣扎，相隔二十年再度聚首后选择面对真相，坦荡向前的故事</li></ul><p><img src="https://pic.rmb.bdstatic.com/b00fa8e4e4546fa4e84105dc8abcc99b.jpeg" alt=""></p><h2 id="走走停停" tabindex="-1">走走停停 <a class="header-anchor" href="#走走停停" aria-label="Permalink to &quot;走走停停&quot;">​</a></h2><ul><li>2024-06-08 中国大陆 103分钟</li><li>类型：家庭 搞笑 剧情</li><li>导演：龙飞</li><li>主演：胡歌 高圆圆 岳红 周野芒 金靖</li><li>简介：脆皮青年吴迪（胡歌饰），工作感情双双失意，沮丧返乡。吴迪“突袭”返乡的行为打破了一家人原本平静的生活，他不仅需要重新面对与家人的“亲密”相处，还要为自己的未来寻找更多的可能。在现实面前多番碰壁后，一次偶然的机会下他与高中同学冯柳柳（高圆圆饰）相遇，随后生活也发生了意想不到的转变。</li></ul><p>我感觉还是值的一看的，有笑点，可能会感觉有点平淡，但是大部分的人生不就是这么平淡么？</p><p><img src="https://m.ykimg.com/0535000066471F9F7B50C00F0701DECB" alt=""></p><h2 id="风平浪静" tabindex="-1">风平浪静 <a class="header-anchor" href="#风平浪静" aria-label="Permalink to &quot;风平浪静&quot;">​</a></h2><ul><li>2020-11-06 中国大陆 119分钟</li><li>类型：剧情 犯罪 爱情</li><li>导演：李霄峰</li><li>主演：章宇 宋佳 王砚辉 李鸿其 邓恩熙</li><li>百科：故事发生在15年前,西河中学的优等生宋浩学习优异,恃才傲物,甚至还有一个富二代同学李唐为他站脚撑腰。但是他怎么也.</li></ul><p><img src="https://img0.baidu.com/it/u=1817662264,701164527&amp;fm=253&amp;fmt=auto?w=800&amp;h=800" alt=""></p><h2 id="南极之恋" tabindex="-1">南极之恋 <a class="header-anchor" href="#南极之恋" aria-label="Permalink to &quot;南极之恋&quot;">​</a></h2><ul><li>2018-02-01 中国大陆 117分钟</li><li>类型：爱情 冒险 灾难</li><li>导演：吴有音</li><li>主演：赵又廷 杨子姗 白雪 孙迪 董杨</li><li>简介：该片改编自吴有音创作的长篇小说《南极绝恋》，讲述了婚庆公司老板吴富春（赵又廷 饰）和高空物理学家荆如意（杨子姗 饰）在南极上空遭遇坠机，两个毫无共同语言的男女，在酷寒冻土、随处都是绝境的南极腹地中，面对伤痛折磨、物资匮尽的困境，两人彼此依存、互生情愫的纯爱故事</li></ul><p>挺好看的，有笑点，在抖音看到了搞笑片段才看的，对，就是拜佛那个片段。</p><p><img src="https://p1.meituan.net/movie/e26cbb3dad9603f9744f19d7bcda0bd9783124.jpg@80q" alt=""></p><h2 id="来福大酒店" tabindex="-1">来福大酒店 <a class="header-anchor" href="#来福大酒店" aria-label="Permalink to &quot;来福大酒店&quot;">​</a></h2><ul><li>2024-06-28 中国大陆 118分钟</li><li>类型：剧情 搞笑 爱情</li><li>导演：刘博文</li><li>主演：黄轩 柳岩 刘洋 张哲华 董宝石</li><li>简介：《来福大酒店》围绕病友之家的主题展开，讲述了一群陌生的人们因各种原因相聚在来福大酒店这栋小小的建筑里，在相互帮助中得到温暖和慰藉的感人故事。</li></ul><p>我很喜欢这类片子，挺有意思的，也很搞笑，黄轩的演技不错，柳岩还是挺漂亮的。</p><p><img src="https://q9.itc.cn/images01/20240630/0a55c6c5171e40c099ccbece97f4ee9c.jpeg" alt=""></p><h2 id="中国乒乓之绝地反击" tabindex="-1">中国乒乓之绝地反击 <a class="header-anchor" href="#中国乒乓之绝地反击" aria-label="Permalink to &quot;中国乒乓之绝地反击&quot;">​</a></h2><ul><li>2023-02-17 中国大陆 137分钟</li><li>类型：剧情 运动 体育</li><li>导演：邓超 俞白眉</li><li>主演：邓超 孙俪 许魏洲 段博文 蔡宜达</li><li>简介：该片改编自上世纪90年代初中国乒乓的真实故事，讲述了1992年至1995年期间，戴敏佳从国外回来担任主帅决心有一番作为，龚枫、白民和、黄昭、侯卓翔、董帅五名运动员在戴敏佳的带领下，在天津世锦赛绝地反击的故事</li></ul><p>现在中国乒乓这么厉害，都快让大家误以为作为国球的乒乓一开始就我们就这么厉害呢，原来也是一步一步艰难的走过来的。拍的不错。最近巴黎奥运会， 我也没事总看乒乓的集锦和名场面采访，许昕真是要笑死我，太搞笑了，哈哈哈哈哈哈哈哈。</p><p><img src="https://p3.itc.cn/images01/20230116/0944edf5117d4ab1acbbd74abf21c982.png" alt=""></p><h2 id="狗阵" tabindex="-1">狗阵 <a class="header-anchor" href="#狗阵" aria-label="Permalink to &quot;狗阵&quot;">​</a></h2><ul><li>2024-06-15 中国大陆 116分钟</li><li>类型：剧情</li><li>导演：管虎</li><li>主演：彭于晏 佟丽娅 贾樟柯 周游 胡晓光</li><li>简介：该片讲述了刑满释放人员二郎为生计而加入打狗队，然而旁人的冷眼和白眼让他始终无法融入生活，在拯救了一只流浪黑狗后，人和狗互相慰藉并得到生命救赎的故事</li></ul><p>这个片子其实是冲着彭于晏去的，看了二十分钟，看不下去了，也不是说彭于晏全程没有台词，就是感觉很平淡，没有看下去的欲望，然后去看电影解说了。 这个片子让我想起了我之前很早看过很类似的片子，都是男主基本上没有台词。陈冠希演的《狗咬狗》，这个电影演的是真的好。 强烈推荐你们看下。</p><p><img src="https://q0.itc.cn/q_70/images01/20240607/6011f2f849544faeadfe8c0edf401db5.jpeg" alt=""></p><p><img src="https://assets.wmoov.com/movie/photo/201410/_H8A0840281MB29_1413273404.jpg" alt=""></p><h2 id="逆行人生" tabindex="-1">逆行人生 <a class="header-anchor" href="#逆行人生" aria-label="Permalink to &quot;逆行人生&quot;">​</a></h2><ul><li>2024-08-09 中国大陆 121分钟</li><li>类型：剧情</li><li>导演：徐峥</li><li>主演：徐峥 辛芷蕾 王骁 贾冰 冯兵</li><li>百科：影片讲述了人到中年的程序员高志垒在经历工作裁员及生活的双重变故后，不得不转行做外卖员，并在送外卖的过程中重新定义人生方向的故事。</li></ul><p>说实话，真不好看，毫无看点，槽点一大堆，应该是我看过徐峥最不好看的电影了。</p><p><img src="https://img2.baidu.com/it/u=3637121694,3428772101&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG?w=800&amp;h=1231" alt=""></p><h2 id="骑鲸少年" tabindex="-1">骑鲸少年 <a class="header-anchor" href="#骑鲸少年" aria-label="Permalink to &quot;骑鲸少年&quot;">​</a></h2><ul><li>2024年8月16日 中国大陆 90分钟</li><li>类型：剧情</li><li>导演：刘盛</li><li>主演：‌韩三明‌ 龚喜 舒芙蓉 朱欣宇</li><li>百科：胡小洲自卑懦弱，常常受到混混邝超的欺负，一次偶然的机会，袁教练教他学会了拳击...</li></ul><p>我个人感觉非常好看的一部片子，强烈推荐大家看一下，里面的拳击对打部分看起来很真实，速度很快且有力量，一看都是练过的。</p><p><img src="https://t11.baidu.com/it/u=3732953200,242616940&amp;fm=30&amp;app=106&amp;f=JPEG?w=613&amp;h=822&amp;s=DB0605C34C128BFD4E91113D03005002" alt=""></p><h2 id="大撒把" tabindex="-1">大撒把 <a class="header-anchor" href="#大撒把" aria-label="Permalink to &quot;大撒把&quot;">​</a></h2><ul><li>1992-08-05 中国大陆 95分钟</li><li>类型：爱情 搞笑 剧情</li><li>导演：夏钢</li><li>主演：葛优 徐帆 张会忠 盖丽丽 孙淳</li><li>百科：空旷的候机大厅,即将与各自爱人分别的男女主人公。男主人公顾颜(葛优饰)正在候机大厅送别即将去加拿大自费留学的妻子...</li></ul><p>葛大爷的电影，挺好看的</p><p><img src="https://b0.bdstatic.com/1d824d71d8dd0ce4c661511e69c4a6ff.jpg@h_1280" alt=""></p>',49),c=[p];function o(r,h,s,m,d,n){return a(),l("div",null,c)}const f=i(t,[["render",o]]);export{b as __pageData,f as default};
